input.content:
/* ==========================================================================
   Relay — operations control room
   Restrained neutral palette, one purposeful accent, compact & numeric-first.
   ========================================================================== */

:root {
  /* Neutrals: cool, low-chroma, layered by elevation */
  --bg:        #0d1013;
  --surface:   #12161a;
  --surface-2: #161b20;
  --surface-3: #1b2127;
  --line:      #262d34;
  --line-soft: #1d2329;
  --text:      #e3e8ec;
  --text-2:    #9aa5ae;
  --text-3:    #67727c;

  /* One purposeful accent — used for selection, live state, primary action */
  --accent:      #3fb9a8;
  --accent-dim:  #1c3b37;
  --accent-text: #7ee0d1;

  /* Severity states — restrained, distinguishable without leaning on color alone */
  --sev-critical: #e06b6b;
  --sev-high:     #d99a52;
  --sev-medium:   #6f9fd8;
  --sev-low:      #6f7e88;
  --sev-critical-bg: #33201f;
  --sev-high-bg:     #302619;
  --sev-medium-bg:   #1d2a38;
  --sev-low-bg:      #20262b;

  --up-good:   var(--accent-text);
  --up-bad:    #e08a7a;
  --down-good: var(--accent-text);
  --down-bad:  #e08a7a;

  --radius: 4px;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", "Segoe UI Mono", Menlo, Consolas, monospace;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --rail-w: 218px;
  --topbar-h: 48px;
}

* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; height: 100%; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 13px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
  font-variant-numeric: tabular-nums;
  overflow-x: hidden;
}

.mono { font-family: var(--mono); font-variant-numeric: tabular-nums; }

h1, h2, h3 { margin: 0; font-weight: 600; letter-spacing: -0.01em; }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.sprite { position: absolute; }

.icon {
  width: 16px; height: 16px; flex: none;
  fill: none; stroke: currentColor; stroke-width: 1.7;
  stroke-linecap: round; stroke-linejoin: round;
}

/* Visible keyboard focus everywhere */
:where(a, button, input, select, [tabindex], summary, dialog):focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: var(--radius);
}
/* Keep focus visible on the custom bar/row controls which use box-shadow too */
.bar:focus-visible, .inc-row:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -1px;
}

.skip {
  position: absolute; left: 8px; top: -60px; z-index: 100;
  background: var(--accent); color: #07110f; padding: 8px 14px;
  font-weight: 600; border-radius: var(--radius); text-decoration: none;
  transition: top .12s ease;
}
.skip:focus { top: 8px; }

kbd.kbd, .kbd {
  font-family: var(--mono); font-size: 10px; line-height: 1;
  color: var(--text-2); background: var(--surface-3);
  border: 1px solid var(--line); border-bottom-width: 2px;
  border-radius: 3px; padding: 3px 5px;
}

/* ------------------------------------------------------------------ layout */
.app { display: flex; min-height: 100vh; }

.main { flex: 1; min-width: 0; display: flex; flex-direction: column; }

/* -------------------------------------------------------------- nav rail */
.rail {
  width: var(--rail-w); flex: none;
  background: var(--surface);
  border-right: 1px solid var(--line);
  display: flex; flex-direction: column;
  position: sticky; top: 0; height: 100vh;
}

.rail-brand {
  height: var(--topbar-h); flex: none;
  display: flex; align-items: center; gap: 9px;
  padding: 0 16px; border-bottom: 1px solid var(--line);
}
.brand-mark {
  width: 22px; height: 22px; display: grid; place-items: center;
  background: var(--accent-dim); color: var(--accent-text);
  border: 1px solid #2a504b; border-radius: var(--radius);
}
.brand-mark .icon { width: 14px; height: 14px; stroke-width: 2; }
.brand-name { font-weight: 700; letter-spacing: -0.02em; font-size: 14px; }
.brand-sub {
  font-family: var(--mono); font-size: 9px; letter-spacing: .14em;
  color: var(--accent-text); border: 1px solid var(--line);
  padding: 1px 4px; border-radius: 2px; margin-left: auto;
}

.rail-nav { padding: 14px 10px; overflow-y: auto; flex: 1; }
.rail-group {
  margin: 14px 8px 7px; font-size: 10px; letter-spacing: .12em;
  text-transform: uppercase; color: var(--text-3); font-weight: 600;
}
.rail-group:first-child { margin-top: 0; }

.nav-item {
  display: flex; align-items: center; gap: 11px;
  width: 100%; padding: 8px 10px; margin: 1px 0;
  color: var(--text-2); background: transparent;
  border: 1px solid transparent; border-radius: var(--radius);
  font: inherit; text-align: left; text-decoration: none;
  cursor: pointer; position: relative;
}
.nav-item .icon { width: 16px; height: 16px; }
.nav-item:hover { background: var(--surface-2); color: var(--text); }
.nav-item.is-active {
  background: var(--surface-3); color: var(--text); font-weight: 600;
  border-color: var(--line);
}
.nav-item.is-active::before {
  content: ""; position: absolute; left: -10px; top: 6px; bottom: 6px;
  width: 2px; background: var(--accent); border-radius: 2px;
}
.nav-item.is-active .icon { color: var(--accent-text); }

.rail-foot {
  flex: none; display: flex; align-items: center; gap: 9px;
  padding: 11px 14px; border-top: 1px solid var(--line);
  flex-wrap: wrap;
}
.avatar {
  width: 26px; height: 26px; flex: none; display: grid; place-items: center;
  background: var(--surface-3); border: 1px solid var(--line);
  border-radius: 50%; font-size: 10px; font-weight: 700; color: var(--text-2);
}
.rail-foot-text { display: flex; flex-direction: column; line-height: 1.25; min-width: 0; }
.rail-foot-text strong { font-weight: 600; font-size: 11px; }
.rail-foot-text small { color: var(--text-3); font-size: 10px; }
.build { margin-left: auto; font-size: 9px; color: var(--text-3); }

/* ------------------------------------------------------------- top bar */
.topbar {
  height: var(--topbar-h); flex: none;
  display: flex; align-items: center; justify-content: space-between;
  gap: 16px; padding: 0 20px;
  background: var(--surface); border-bottom: 1px solid var(--line);
  position: sticky; top: 0; z-index: 20;
}
.topbar-left, .topbar-right { display: flex; align-items: center; gap: 16px; min-width: 0; }
.crumb { color: var(--text-3); white-space: nowrap; }
.crumb strong { color: var(--text); font-weight: 600; }
.crumb-sep { color: var(--line); margin: 0 2px; }
.env {
  font-family: var(--mono); font-size: 10px; letter-spacing: .04em;
  color: var(--text-2); background: var(--surface-2);
  border: 1px solid var(--line); padding: 3px 7px; border-radius: 2px;
  white-space: nowrap;
}
.topbar-right { gap: 18px; font-size: 11px; color: var(--text-2); }
.live { display: inline-flex; align-items: center; gap: 7px; color: var(--accent-text); font-weight: 600; }
.live-dot {
  width: 7px; height: 7px; border-radius: 50%; background: var(--accent);
  box-shadow: 0 0 0 0 rgba(63,185,168,.5); animation: pulse 2.4s infinite;
}
@keyframes pulse {
  0%   { box-shadow: 0 0 0 0 rgba(63,185,168,.45); }
  70%  { box-shadow: 0 0 0 6px rgba(63,185,168,0); }
  100% { box-shadow: 0 0 0 0 rgba(63,185,168,0); }
}
@media (prefers-reduced-motion: reduce) {
  .live-dot { animation: none; }
  * { scroll-behavior: auto !important; }
}
.sync, .clock { white-space: nowrap; }
.clock { color: var(--text); }
.topbar-divider { width: 1px; height: 18px; background: var(--line); }
.health { display: inline-flex; align-items: center; gap: 7px; white-space: nowrap; }
.health-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--sev-high); }
.health.is-ok .health-dot { background: var(--accent); }
.health.is-degraded .health-dot { background: var(--sev-high); }
.health.is-critical .health-dot { background: var(--sev-critical); }

/* ------------------------------------------------------------- content */
.content { padding: 20px 22px 28px; width: 100%; max-width: 1500px; }

.page-head {
  display: flex; align-items: flex-end; justify-content: space-between;
  gap: 16px; margin-bottom: 18px; flex-wrap: wrap;
}
.page-head h1 { font-size: 17px; }
.page-sub { margin: 3px 0 0; color: var(--text-3); font-size: 12px; }
.page-actions { display: flex; align-items: center; gap: 14px; }
.updated { font-size: 11px; color: var(--text-3); white-space: nowrap; }

.btn {
  display: inline-flex; align-items: center; gap: 7px;
  font: inherit; font-size: 12px; font-weight: 600;
  color: var(--text); background: var(--surface-2);
  border: 1px solid var(--line); border-radius: var(--radius);
  padding: 7px 11px; cursor: pointer; white-space: nowrap;
}
.btn:hover { background: var(--surface-3); border-color: #333c44; }
.btn:active { transform: translateY(1px); }
.btn .icon { width: 14px; height: 14px; }
.btn-sm { padding: 6px 10px; font-weight: 500; color: var(--text-2); }

.btn-accent {
  background: var(--accent); color: #06120f; border-color: var(--accent);
}
.btn-accent:hover { background: #4fcabb; border-color: #4fcabb; }
.btn-accent:disabled { background: var(--surface-3); color: var(--text-3); border-color: var(--line); cursor: default; }

.link-btn {
  background: none; border: 0; padding: 0; color: var(--accent-text);
  font: inherit; text-decoration: underline; text-underline-offset: 2px;
  cursor: pointer;
}

/* ------------------------------------------------------------- metrics */
.metrics {
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 1px; background: var(--line);
  border: 1px solid var(--line); border-radius: var(--radius);
  overflow: hidden; margin-bottom: 18px;
}
.metric { background: var(--surface); padding: 13px 15px 14px; min-width: 0; }
.metric-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.metric-label {
  font-size: 11px; color: var(--text-3); font-weight: 600;
  text-transform: uppercase; letter-spacing: .06em; white-space: nowrap;
}
.metric-spark { display: flex; align-items: flex-end; gap: 2px; height: 16px; }
.metric-spark i { width: 3px; background: var(--line); border-radius: 1px 1px 0 0; }
.metric-spark i.on { background: var(--accent-dim); }
.metric-value {
  font-family: var(--mono); font-size: 25px; font-weight: 600;
  letter-spacing: -0.02em; margin: 7px 0 6px; line-height: 1;
  color: var(--text); white-space: nowrap;
}
.metric-unit { font-size: 14px; color: var(--text-2); }
.metric-trend { display: flex; align-items: center; gap: 6px; font-size: 11px; }
.trend-chip {
  display: inline-flex; align-items: center; gap: 3px;
  font-family: var(--mono); font-weight: 600; padding: 1px 5px;
  border-radius: 3px; white-space: nowrap;
}
.trend-chip .icon { width: 11px; height: 11px; stroke-width: 2.2; }
.trend-chip.good { color: var(--accent-text); background: var(--accent-dim); }
.trend-chip.bad  { color: #e79a8a; background: #33211f; }
.trend-context { color: var(--text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* ------------------------------------------------------------- panels */
.panel {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--radius);
}
.panel-head {
  display: flex; align-items: flex-start; justify-content: space-between;
  gap: 14px; padding: 13px 15px; border-bottom: 1px solid var(--line-soft);
}
.panel-head h2 { font-size: 13px; }
.panel-sub { margin: 2px 0 0; color: var(--text-3); font-size: 11px; }

/* ------------------------------------------------------------- chart */
.chart-panel { margin-bottom: 18px; }
.chart-stats { display: flex; gap: 22px; }
.chart-stat { display: flex; flex-direction: column; gap: 2px; text-align: right; }
.chart-stat dt { font-size: 10px; color: var(--text-3); text-transform: uppercase; letter-spacing: .06em; }
.chart-stat dd { margin: 0; font-family: var(--mono); font-size: 14px; font-weight: 600; }
.chart-stat dd.hot { color: var(--sev-high); }

.chart-readout {
  min-height: 18px; padding: 6px 15px 0;
  font-family: var(--mono); font-size: 11px; color: var(--accent-text);
}
.chart-readout .placeholder { color: var(--text-3); }

.chart-body { display: flex; gap: 0; padding: 8px 15px 0; }
.chart-yaxis {
  width: 34px; flex: none; height: 160px;
  display: flex; flex-direction: column; justify-content: space-between;
  align-items: flex-end; padding-right: 8px;
  font-family: var(--mono); font-size: 10px; color: var(--text-3);
}
.chart-plot { position: relative; flex: 1; min-width: 0; height: 160px; }
.gridlines { position: absolute; inset: 0; display: flex; flex-direction: column; justify-content: space-between; }
.gridlines i { height: 1px; background: var(--line-soft); display: block; }
.bars {
  position: absolute; inset: 0; display: flex; align-items: flex-end;
  gap: 3px; z-index: 1;
}
.bar {
  flex: 1; min-width: 0; position: relative;
  display: flex; align-items: flex-end; justify-content: center;
  background: transparent; border: 0; padding: 0; cursor: pointer;
  height: 100%;
}
.bar-fill {
  width: 100%; background: #2b3d3c; border-radius: 1px 1px 0 0;
  border-top: 1px solid #3a5552;
  transition: background .12s ease;
}
.bar:hover .bar-fill { background: #3a5754; }
.bar.over .bar-fill { background: #5a4030; border-top-color: #7a5638; }
.bar.over:hover .bar-fill { background: #6d4c38; }
.bar.is-focus .bar-fill { background: var(--accent); border-top-color: var(--accent-text); }
.bar.is-focus::after {
  content: ""; position: absolute; left: 50%; top: 0; bottom: 0;
  width: 1px; background: var(--accent); opacity: .5; transform: translateX(-50%);
}
.capline {
  position: absolute; left: 0; right: 0; bottom: 85%;
  border-top: 1px dashed #6b5433; z-index: 2; pointer-events: none;
}
.capline span {
  position: absolute; right: 0; top: -14px;
  font-family: var(--mono); font-size: 9px; color: #9a7c4c;
  background: var(--surface); padding: 0 3px;
}
.chart-xaxis { display: flex; padding: 0 15px; }
.chart-xaxis > span { width: 34px; flex: none; }
.chart-xaxis-inner {
  flex: 1; display: flex; justify-content: space-between;
  font-family: var(--mono); font-size: 10px; color: var(--text-3);
  padding-top: 6px;
}
.chart-xaxis-inner span { flex: 1; text-align: center; }
.chart-foot {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 11px 15px; border-top: 1px solid var(--line-soft); margin-top: 10px;
  font-size: 11px; color: var(--text-3); flex-wrap: wrap;
}
.legend { display: inline-flex; align-items: center; gap: 7px; }
.legend-swatch { width: 10px; height: 10px; background: #2b3d3c; border: 1px solid #3a5552; border-radius: 1px; }
.hint { font-family: var(--mono); font-size: 10px; }

/* ------------------------------------------------------- incidents + detail */
.lower {
  display: grid; grid-template-columns: minmax(0, 1fr) 330px;
  gap: 18px; align-items: start;
}

.count {
  font-size: 11px; color: var(--text-2);
  background: var(--surface-2); border: 1px solid var(--line);
  padding: 3px 8px; border-radius: 10px; white-space: nowrap;
}

.filters {
  display: flex; align-items: center; gap: 8px; padding: 10px 15px;
  border-bottom: 1px solid var(--line-soft); flex-wrap: wrap;
}
.search {
  display: flex; align-items: center; gap: 7px; flex: 1 1 200px;
  min-width: 0; background: var(--surface-2);
  border: 1px solid var(--line); border-radius: var(--radius);
  padding: 0 8px; height: 32px;
}
.search:focus-within { border-color: var(--accent); outline: 1px solid var(--accent-dim); }
.search .icon { width: 14px; height: 14px; color: var(--text-3); }
.search input {
  flex: 1; min-width: 0; background: transparent; border: 0; outline: 0;
  color: var(--text); font: inherit; font-size: 12px;
}
.search input::placeholder { color: var(--text-3); }
.search input::-webkit-search-cancel-button { filter: grayscale(1) brightness(1.4); cursor: pointer; }
.search .kbd { flex: none; }

.sel { position: relative; }
.sel select {
  appearance: none; -webkit-appearance: none;
  font: inherit; font-size: 12px; color: var(--text-2);
  background: var(--surface-2); border: 1px solid var(--line);
  border-radius: var(--radius); padding: 7px 26px 7px 10px; height: 32px;
  cursor: pointer;
}
.sel::after {
  content: ""; position: absolute; right: 10px; top: 50%;
  width: 5px; height: 5px; border-right: 1.5px solid var(--text-3);
  border-bottom: 1.5px solid var(--text-3); transform: translateY(-70%) rotate(45deg);
  pointer-events: none;
}
.sel select:hover { border-color: #333c44; }
.sel option { background: var(--surface-2); color: var(--text); }

.table-wrap { position: relative; min-height: 180px; }
.inc-table { width: 100%; border-collapse: collapse; table-layout: fixed; }
.inc-table th {
  text-align: left; font-size: 10px; font-weight: 600;
  text-transform: uppercase; letter-spacing: .06em; color: var(--text-3);
  padding: 8px 12px; border-bottom: 1px solid var(--line);
  background: var(--surface-2); white-space: nowrap;
}
/* Fixed column widths keep dense data aligned */
.inc-table th:nth-child(1) { width: 96px; }
.inc-table th:nth-child(2) { width: 22%; }
.inc-table th:nth-child(3) { width: auto; }
.inc-table th:nth-child(4) { width: 76px; }
.inc-table th:nth-child(5) { width: 100px; }
.inc-table th:nth-child(6) { width: 116px; }
.inc-table th.num, .inc-table td.num { text-align: right; }

.inc-row { cursor: pointer; border-bottom: 1px solid var(--line-soft); }
.inc-row:last-child { border-bottom: 0; }
.inc-row td {
  padding: 9px 12px; font-size: 12px; vertical-align: middle;
  color: var(--text-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.inc-row:hover { background: var(--surface-2); }
.inc-row.is-selected { background: var(--surface-3); }
.inc-row.is-selected td:first-child { box-shadow: inset 2px 0 0 var(--accent); }
.inc-row.is-selected .inc-id { color: var(--text); }

.sev {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 10px; font-weight: 700; letter-spacing: .04em;
  text-transform: uppercase; padding: 2px 6px; border-radius: 2px;
  border: 1px solid transparent;
}
.sev::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: currentColor; }
.sev-critical { color: var(--sev-critical); background: var(--sev-critical-bg); border-color: #4a2a28; }
.sev-high     { color: var(--sev-high);     background: var(--sev-high-bg);     border-color: #473520; }
.sev-medium   { color: var(--sev-medium);   background: var(--sev-medium-bg);   border-color: #2b3f55; }
.sev-low      { color: var(--sev-low);      background: var(--sev-low-bg);      border-color: #2c353c; }

.cell-service { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.inc-service { color: var(--text); font-weight: 600; font-family: var(--mono); font-size: 11px; overflow: hidden; text-overflow: ellipsis; }
.inc-id { color: var(--text-3); font-family: var(--mono); font-size: 10px; }
.cell-title { color: var(--text-2); }
.cell-age { font-family: var(--mono); color: var(--text); }
.cell-owner.unassigned { color: var(--sev-high); font-style: italic; }
.status {
  display: inline-flex; align-items: center; gap: 6px; font-size: 11px; white-space: nowrap;
}
.status::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--text-3); }
.status-open::before { background: var(--sev-high); }
.status-investigating::before { background: var(--sev-critical); }
.status-monitoring::before { background: var(--sev-medium); }
.status-acknowledged::before { background: var(--accent); box-shadow: 0 0 0 2px var(--accent-dim); }
.status-acknowledged { color: var(--accent-text); }

/* Empty / filter state */
.empty {
  padding: 34px 20px 40px; text-align: center;
  display: flex; flex-direction: column; align-items: center; gap: 8px;
}
.empty-icon { width: 26px; height: 26px; color: var(--text-3); stroke-width: 1.4; }
.empty h3 { font-size: 13px; }
.empty p { margin: 0; color: var(--text-3); font-size: 12px; max-width: 320px; }
.empty .btn { margin-top: 6px; }

/* ------------------------------------------------------------- detail */
.detail-panel { position: sticky; top: calc(var(--topbar-h) + 18px); }
.detail-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 13px 15px; border-bottom: 1px solid var(--line-soft);
}
.detail-head h2 { font-size: 13px; }
.detail-body { padding: 15px; }
.detail-title-line {
  display: flex; align-items: flex-start; justify-content: space-between;
  gap: 10px; margin-bottom: 4px;
}
.detail-id { font-family: var(--mono); font-size: 11px; color: var(--text-3); }
.detail-title { font-size: 15px; line-height: 1.35; margin: 4px 0 12px; }
.detail-tags { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 16px; }

.detail-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 0; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; margin-bottom: 16px; }
.field { padding: 9px 11px; border-bottom: 1px solid var(--line-soft); }
.field:nth-child(odd) { border-right: 1px solid var(--line-soft); }
.field:nth-last-child(-n+2) { border-bottom: 0; }
.field dt { font-size: 10px; text-transform: uppercase; letter-spacing: .06em; color: var(--text-3); margin-bottom: 3px; }
.field dd { margin: 0; font-size: 12px; color: var(--text); }
.field dd.mono { font-size: 12px; }

.section-label { font-size: 10px; text-transform: uppercase; letter-spacing: .08em; color: var(--text-3); font-weight: 600; margin: 0 0 8px; }
.timeline { list-style: none; margin: 0 0 16px; padding: 0 0 0 14px; border-left: 1px solid var(--line); }
.timeline li { position: relative; padding: 0 0 11px 2px; font-size: 11px; color: var(--text-2); }
.timeline li:last-child { padding-bottom: 0; }
.timeline li::before {
  content: ""; position: absolute; left: -18px; top: 4px;
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--surface); border: 1px solid var(--line);
}
.timeline li:first-child::before { background: var(--accent); border-color: var(--accent); }
.timeline time { display: block; font-family: var(--mono); font-size: 10px; color: var(--text-3); }

.detail-actions { display: flex; gap: 8px; }
.detail-actions .btn { flex: 1; justify-content: center; }
.ack-note {
  margin: 10px 0 0; font-size: 11px; color: var(--text-3);
  display: flex; align-items: center; gap: 6px;
}
.ack-note .icon { width: 13px; height: 13px; color: var(--accent-text); }

.detail-placeholder { padding: 44px 20px; text-align: center; color: var(--text-3); }
.detail-placeholder .icon { width: 28px; height: 28px; margin-bottom: 10px; stroke-width: 1.3; }
.detail-placeholder h3 { font-size: 13px; color: var(--text-2); margin-bottom: 5px; }
.detail-placeholder p { margin: 0; font-size: 11px; }

/* ------------------------------------------------------------- footer */
.foot {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  margin-top: 20px; padding-top: 14px; border-top: 1px solid var(--line-soft);
  font-size: 11px; color: var(--text-3); flex-wrap: wrap;
}
.foot .kbd { margin: 0 2px; }

/* ------------------------------------------------------------- dialog */
.help-dialog {
  width: min(420px, calc(100vw - 32px));
  background: var(--surface); color: var(--text);
  border: 1px solid var(--line); border-radius: var(--radius);
  padding: 0; box-shadow: 0 24px 60px rgba(0,0,0,.6);
}
.help-dialog::backdrop { background: rgba(5,8,10,.72); }
.dialog-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 13px 15px; border-bottom: 1px solid var(--line);
}
.dialog-head h2 { font-size: 13px; }
.icon-btn {
  display: grid; place-items: center; width: 26px; height: 26px;
  background: var(--surface-2); border: 1px solid var(--line);
  border-radius: var(--radius); color: var(--text-2); cursor: pointer;
}
.icon-btn:hover { color: var(--text); background: var(--surface-3); }
.dialog-body { padding: 15px; }
.shortcuts { margin: 0 0 14px; }
.shortcuts > div {
  display: flex; align-items: baseline; justify-content: space-between;
  gap: 14px; padding: 6px 0; border-bottom: 1px solid var(--line-soft);
}
.shortcuts > div:last-child { border-bottom: 0; }
.shortcuts dt { font-family: var(--mono); font-size: 11px; color: var(--accent-text); white-space: nowrap; }
.shortcuts dd { margin: 0; font-size: 11px; color: var(--text-2); text-align: right; }
.dialog-note { margin: 0; font-size: 11px; color: var(--text-3); line-height: 1.55; border-top: 1px solid var(--line-soft); padding-top: 12px; }

/* =======================================================================
   Responsive
   ======================================================================= */

@media (max-width: 1180px) {
  .lower { grid-template-columns: minmax(0, 1fr) 290px; }
  .content { padding: 18px 18px 26px; }
}

/* Tablet: rail collapses to icons only */
@media (max-width: 980px) {
  :root { --rail-w: 56px; }
  .brand-name, .brand-sub, .nav-label, .rail-group, .rail-foot-text, .build { display: none; }
  .rail-brand { justify-content: center; padding: 0; }
  .rail-nav { padding: 12px 8px; }
  .nav-item { justify-content: center; padding: 10px 0; }
  .nav-item.is-active::before { left: -8px; }
  .rail-foot { justify-content: center; padding: 11px 0; }
  .lower { grid-template-columns: minmax(0, 1fr); }
  .detail-panel { position: static; }
  .metrics { grid-template-columns: repeat(2, 1fr); }
}

/* Mobile */
@media (max-width: 620px) {
  .topbar { padding: 0 12px; }
  .topbar-left .env { display: none; }
  .topbar-right { gap: 12px; }
  .sync { display: none; }
  .health { display: none; }
  .topbar-divider { display: none; }

  .content { padding: 14px 12px 22px; }
  .page-head { align-items: flex-start; }
  .page-head h1 { font-size: 16px; }
  .page-actions .updated { display: none; }

  .metrics { grid-template-columns: repeat(2, 1fr); }
  .metric { padding: 11px 11px 12px; }
  .metric-value { font-size: 21px; }
  .metric-label { font-size: 9.5px; letter-spacing: .04em; }

  .chart-stats { gap: 14px; }
  .chart-stat dd { font-size: 12px; }
  .chart-yaxis { width: 26px; font-size: 9px; padding-right: 5px; }
  .chart-xaxis > span { width: 26px; }
  .bars { gap: 2px; }
  .chart-xaxis-inner span:nth-child(even) { visibility: hidden; } /* declutter labels */
  .chart-xaxis-inner { font-size: 9px; }
  .chart-foot .hint { display: none; }

  .filters { padding: 10px 12px; }
  .search { flex-basis: 100%; }
  .sel { flex: 1; }
  .sel select { width: 100%; }

  /* On narrow screens hide the least-critical columns; keep severity,
     service/id, age and status readable with no horizontal scroll. */
  .inc-table th:nth-child(3), .inc-table td.cell-title { display: none; }
  .inc-table th:nth-child(5), .inc-table td.cell-owner { display: none; }
  .inc-table th:nth-child(1) { width: 84px; }
  .inc-table th:nth-child(2) { width: auto; }
  .inc-table th:nth-child(4) { width: 58px; }
  .inc-table th:nth-child(6) { width: 104px; }
  .inc-table th, .inc-row td { padding: 9px 7px; }
  .sev { font-size: 9px; padding: 2px 4px; gap: 4px; }
  .status { font-size: 10px; }
  .foot { flex-direction: column; align-items: flex-start; gap: 8px; }
}

@media (max-width: 400px) {
  .chart-stats .chart-stat:first-child { display: none; }
  .trend-context { display: none; }
  .metric-spark { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; }
}

