input.content:
/* ==========================================================================
   Relay — operations control room
   Vanilla JS. No frameworks, no network requests at runtime.
   Data is seeded from DATA.json (fetched when served over http); when opened
   directly via file:// the inline #seed JSON is used as an exact fallback.
   ========================================================================== */
(function () {
  "use strict";

  /* ---------------------------------------------------------------- helpers */
  var $  = function (s, r) { return (r || document).querySelector(s); };
  var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };
  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }
  function icon(id) {
    var svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("class", "icon");
    svg.setAttribute("aria-hidden", "true");
    var use = document.createElementNS("http://www.w3.org/2000/svg", "use");
    use.setAttribute("href", "#" + id);
    svg.appendChild(use);
    return svg;
  }
  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  function pad(n) { return n < 10 ? "0" + n : "" + n; }
  function timeStr(d) { return pad(d.getHours()) + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds()); }
  function announce(msg) { $("#announcer").textContent = msg; }

  /* ------------------------------------------------------------- constants */
  var CAP = 100;          // chart vertical scale (% of capacity)
  var CAP_TARGET = 85;    // dashed target line
  var SEV_RANK = { critical: 0, high: 1, medium: 2, low: 3 };
  var SEV_ORDER = ["critical", "high", "medium", "low"];
  var CONTEXT = {
    "Events / min": "vs. prior 24 h",
    "P95 latency":  "vs. prior 24 h",
    "Error rate":   "vs. prior 24 h",
    "Queue depth":  "vs. prior 24 h"
  };
  var STATUS_RANK = { open: 0, investigating: 1, monitoring: 2, acknowledged: 3 };
  var TIMELINE = {
    critical: [
      ["Detected by payments-api latency probe", "12m ago"],
      ["PagerDuty escalated to on-call primary", "11m ago"],
      ["Investigation started by M. Chen", "9m ago"]
    ],
    high: [
      ["Detected by queue-depth monitor", "31m ago"],
      ["Runbook linked: retry backlog triage", "30m ago"]
    ],
    medium: [
      ["SLO burn-rate alert fired", "1h 08m ago"],
      ["Mitigation applied, now monitoring", "46m ago"]
    ],
    low: [
      ["Threshold crossed for partner lag", "3h 42m ago"]
    ]
  };

  /* ----------------------------------------------------------------- state */
  var S = {
    data: null,
    incidents: [],       // working copy (acknowledgement mutates status)
    selected: "INC-2841",
    q: "",
    severity: "all",
    status: "all",
    focusHour: null,
    lastRefresh: new Date()
  };

  /* ------------------------------------------------------------------ boot */
  function loadData(cb) {
    var fallback = function () {
      try { return JSON.parse($("#seed").textContent); }
      catch (e) { return null; }
    };
    // fetch() is unavailable or blocked for file:// — use the inline seed then.
    if (typeof fetch !== "function" || location.protocol === "file:") {
      cb(fallback());
      return;
    }
    fetch("DATA.json", { cache: "no-store" })
      .then(function (r) { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
      .then(function (d) { cb(d); })
      .catch(function () { cb(fallback()); });
  }

  function init() {
    loadData(function (d) {
      if (!d || !d.metrics) {
        document.querySelector(".content").innerHTML =
          '<p style="padding:24px;color:#e08a7a">Unable to load dashboard data.</p>';
        return;
      }
      S.data = d;
      // Clone so the seed stays pristine if the dashboard is re-initialised.
      S.incidents = d.incidents.map(function (x) { return Object.assign({}, x); });
      renderMetrics();
      renderChart();
      renderFilters();
      bindGlobal();
      renderTable();
      renderDetail();
      startClock();
      setHealth();
      // Announce initial context for screen readers.
      announce("Relay operations overview loaded. " + S.incidents.length + " active incidents.");
    });
  }

  /* --------------------------------------------------------------- metrics */
  function splitValue(v) {
    var m = /^([\d,]+(?:\.\d+)?)\s*(.*)$/.exec(v);
    return m ? { num: m[1], unit: m[2] } : { num: v, unit: "" };
  }

  function renderMetrics() {
    var host = $("#metrics");
    host.innerHTML = "";
    S.data.metrics.forEach(function (m, i) {
      var cell = el("div", "metric");

      var top = el("div", "metric-top");
      top.appendChild(el("span", "metric-label", m.label));
      // tiny deterministic sparkline, purely decorative
      var spark = el("div", "metric-spark");
      spark.setAttribute("aria-hidden", "true");
      var heights = [[5, 8, 6, 11, 9, 14, 12, 16],
                     [14, 12, 13, 9, 10, 7, 8, 6],
                     [6, 7, 6, 9, 8, 11, 10, 13],
                     [15, 13, 12, 13, 10, 9, 7, 6]][i % 4];
      heights.forEach(function (h) { var b = el("i"); b.style.height = h + "px"; spark.appendChild(b); });
      spark.childNodes[spark.childNodes.length - 1].classList.add("on");
      top.appendChild(spark);
      cell.appendChild(top);

      var parts = splitValue(m.value);
      var val = el("div", "metric-value");
      val.appendChild(document.createTextNode(parts.num));
      if (parts.unit) { var u = el("span", "metric-unit", " " + parts.unit); val.appendChild(u); }
      cell.appendChild(val);

      var trend = el("div", "metric-trend");
      var good = metricGood(m);
      var chip = el("span", "trend-chip " + (good ? "good" : "bad"));
      chip.appendChild(icon(m.direction === "up" ? "i-up" : "i-down"));
      chip.appendChild(document.createTextNode(m.change));
      // For screen readers: spell out the meaning, not just the glyph.
      chip.setAttribute("aria-label", "Trend " + m.change + ", " + (good ? "favourable" : "needs attention"));
      trend.appendChild(chip);
      trend.appendChild(el("span", "trend-context", CONTEXT[m.label] || "vs. prior 24 h"));
      cell.appendChild(trend);

      host.appendChild(cell);
    });
  }

  // Whether an up/down change is favourable for this particular metric.
  function metricGood(m) {
    if (m.label === "Events / min" || m.label === "Error rate") return m.direction === "down";
    if (m.label === "P95 latency" || m.label === "Queue depth") return m.direction === "down";
    return m.direction === "down";
  }

  /* ----------------------------------------------------------------- chart */
  function hourLabels() {
    // 24 hourly buckets ending at the current hour, labelled every 4 h.
    var out = [], now = new Date();
    for (var i = 23; i >= 0; i--) {
      var d = new Date(now.getTime() - i * 3600000);
      out.push({ h: d.getHours(), label: pad(d.getHours()) + ":00" });
    }
    return out;
  }

  function renderChart() {
    var vals = S.data.throughput;
    var hours = hourLabels();
    var max = Math.max.apply(null, vals);
    var min = Math.min.apply(null, vals);
    var avg = Math.round(vals.reduce(function (a, b) { return a + b; }, 0) / vals.length);
    var over = vals.filter(function (v) { return v > CAP_TARGET; }).length;

    // summary stats
    var stats = $("#chart-stats");
    stats.innerHTML = "";
    [["Average", avg + "%"], ["Peak", max + "%"], ["Over target", over + " h"]].forEach(function (p) {
      var box = el("div", "chart-stat");
      box.appendChild(el("dt", null, p[0]));
      var dd = el("dd", p[0] === "Over target" && over > 0 ? "hot" : "", p[1]);
      box.appendChild(dd);
      stats.appendChild(box);
    });

    // y axis
    var ya = $("#chart-yaxis");
    ya.innerHTML = "";
    [100, 75, 50, 25, 0].forEach(function (v) { ya.appendChild(el("span", null, v + "%")); });

    // x axis
    var xa = $("#chart-xaxis-inner");
    xa.innerHTML = "";
    hours.forEach(function (hh, i) {
      // Show a label every 4 hours, but keep the final one always.
      var show = i % 4 === 0 || i === hours.length - 1;
      xa.appendChild(el("span", null, show ? hh.label : ""));
    });

    // bars
    var bars = $("#chart-bars");
    bars.innerHTML = "";
    vals.forEach(function (v, i) {
      var b = el("button", "bar" + (v > CAP_TARGET ? " over" : ""));
      b.type = "button";
      b.dataset.i = i;
      b.dataset.v = v;
      b.setAttribute("role", "button");
      b.setAttribute("aria-label",
        "Hour " + hours[i].label + ", " + v + " percent of capacity" +
        (v > CAP_TARGET ? ", above the 85 percent target" : ""));
      var fill = el("span", "bar-fill");
      fill.style.height = Math.max(2, (v / CAP) * 100) + "%";
      b.appendChild(fill);
      bars.appendChild(b);
    });

    bars.addEventListener("focusin", function (e) {
      var b = e.target.closest(".bar");
      if (b) setFocusHour(parseInt(b.dataset.i, 10));
    });
    bars.addEventListener("click", function (e) {
      var b = e.target.closest(".bar");
      if (b) { setFocusHour(parseInt(b.dataset.i, 10)); b.focus(); }
    });

    $("#chart-readout").innerHTML =
      '<span class="placeholder">Range ' + min + "%–" + max + "% across 24 h · select a bar for detail</span>";
  }

  function setFocusHour(i) {
    var vals = S.data.throughput;
    var hours = hourLabels();
    S.focusHour = i;
    $$(".bar").forEach(function (b) { b.classList.toggle("is-focus", parseInt(b.dataset.i, 10) === i); });
    var v = vals[i];
    var readout = $("#chart-readout");
    readout.innerHTML = "";
    var strong = el("strong", null, hours[i].label);
    readout.appendChild(strong);
    readout.appendChild(document.createTextNode(
      "  ·  " + v + "% of capacity  ·  " +
      (v > CAP_TARGET ? "▲ " + (v - CAP_TARGET) + " pp above target" : "within target") +
      "  ·  hour " + (i + 1) + " of 24"
    ));
  }

  /* --------------------------------------------------------------- filters */
  function renderFilters() {
    var q = $("#q"), sev = $("#f-severity"), st = $("#f-status");
    q.value = S.q; sev.value = S.severity; st.value = S.status;
  }

  function activeFilterText() {
    var bits = [];
    if (S.q) bits.push('text “' + S.q + '”');
    if (S.severity !== "all") bits.push("severity " + S.severity);
    if (S.status !== "all") bits.push("status " + S.status);
    return bits.length ? bits.join(", ") : null;
  }

  function visibleIncidents() {
    var q = S.q.trim().toLowerCase();
    return S.incidents.filter(function (inc) {
      if (S.severity !== "all" && inc.severity !== S.severity) return false;
      if (S.status !== "all" && inc.status !== S.status) return false;
      if (q) {
        var hay = [inc.id, inc.service, inc.owner, inc.title, inc.severity, inc.status]
          .join(" ").toLowerCase();
        if (hay.indexOf(q) === -1) return false;
      }
      return true;
    }).sort(function (a, b) {
      var s = SEV_RANK[a.severity] - SEV_RANK[b.severity];
      if (s) return s;
      return (STATUS_RANK[a.status] - STATUS_RANK[b.status]) || a.id.localeCompare(b.id);
    });
  }

  /* ----------------------------------------------------------------- table */
  function renderTable() {
    var list = visibleIncidents();
    var body = $("#inc-body");
    var empty = $("#empty");
    var table = $(".inc-table");
    body.innerHTML = "";

    $("#result-count").textContent = list.length === S.incidents.length
      ? list.length + " active"
      : list.length + " of " + S.incidents.length;

    if (!list.length) {
      table.hidden = true;
      empty.hidden = false;
      var f = activeFilterText();
      $("#empty-detail").textContent = f
        ? "No incidents match " + f + ". Try a different term or clear the filters."
        : "There are no incidents in the queue.";
      $("#empty-clear").hidden = !f;
      return;
    }
    table.hidden = false;
    empty.hidden = true;

    // Keep a valid selection: prefer the current one, else the top visible row.
    if (!list.some(function (x) { return x.id === S.selected; })) {
      S.selected = list[0].id;
      renderDetail();
    }

    list.forEach(function (inc) {
      var tr = el("tr", "inc-row" + (inc.id === S.selected ? " is-selected" : ""));
      tr.setAttribute("role", "row");
      tr.tabIndex = 0;
      tr.dataset.id = inc.id;
      tr.setAttribute("aria-selected", inc.id === S.selected ? "true" : "false");
      tr.setAttribute("aria-label",
        inc.severity + " severity, " + inc.title + ", " + inc.service +
        ", age " + inc.age + ", owner " + inc.owner + ", status " + inc.status +
        ". Press Enter to open details.");

      // Severity
      var td1 = el("td"); td1.setAttribute("role", "cell");
      var sev = el("span", "sev sev-" + inc.severity, inc.severity);
      td1.appendChild(sev); tr.appendChild(td1);

      // Service / ID
      var td2 = el("td"); td2.setAttribute("role", "cell");
      var c = el("div", "cell-service");
      c.appendChild(el("span", "inc-service", inc.service));
      c.appendChild(el("span", "inc-id", inc.id));
      td2.appendChild(c); tr.appendChild(td2);

      // Title
      var td3 = el("td", "cell-title"); td3.setAttribute("role", "cell");
      td3.appendChild(document.createTextNode(inc.title)); tr.appendChild(td3);

      // Age
      var td4 = el("td", "num cell-age"); td4.setAttribute("role", "cell");
      td4.appendChild(document.createTextNode(inc.age)); tr.appendChild(td4);

      // Owner
      var td5 = el("td", "cell-owner" + (inc.owner === "Unassigned" ? " unassigned" : ""));
      td5.setAttribute("role", "cell");
      td5.appendChild(document.createTextNode(inc.owner)); tr.appendChild(td5);

      // Status
      var td6 = el("td"); td6.setAttribute("role", "cell");
      var st = el("span", "status status-" + inc.status);
      // human-friendly label with the initial capital
      st.appendChild(document.createTextNode(inc.status.charAt(0).toUpperCase() + inc.status.slice(1)));
      td6.appendChild(st); tr.appendChild(td6);

      body.appendChild(tr);
    });
  }

  function selectedIncident() {
    return S.incidents.filter(function (x) { return x.id === S.selected; })[0] || null;
  }

  function selectRow(id, focusRow) {
    S.selected = id;
    $$(".inc-row").forEach(function (r) {
      var on = r.dataset.id === id;
      r.classList.toggle("is-selected", on);
      r.setAttribute("aria-selected", on ? "true" : "false");
    });
    renderDetail();
    if (focusRow) {
      var r = $('.inc-row[data-id="' + id + '"]');
      if (r) r.focus();
    }
    var inc = selectedIncident();
    if (inc) announce("Selected " + inc.id + ", " + inc.title);
  }

  /* ---------------------------------------------------------------- detail */
  function renderDetail() {
    var host = $("#detail");
    var inc = selectedIncident();
    host.innerHTML = "";

    if (!inc) {
      var ph = el("div", "detail-placeholder");
      ph.appendChild(icon("i-panel"));
      ph.appendChild(el("h3", null, "No incident selected"));
      ph.appendChild(el("p", null, "Choose a row from the incident queue to see its detail."));
      host.appendChild(ph);
      return;
    }

    var head = el("div", "detail-head");
    head.appendChild(el("h2", null, "Incident detail", "id", "detail-title"));
    head.setAttribute("id", "detail");
    var close = el("button", "icon-btn");
    close.type = "button";
    close.setAttribute("aria-label", "Clear selection");
    close.appendChild(icon("i-x"));
    close.addEventListener("click", function () {
      S.selected = null;
      $$(".inc-row").forEach(function (r) {
        r.classList.remove("is-selected");
        r.setAttribute("aria-selected", "false");
      });
      renderDetail();
      announce("Incident selection cleared");
    });
    head.appendChild(close);
    host.appendChild(head);

    var body = el("div", "detail-body");

    var tline = el("div", "detail-title-line");
    tline.appendChild(el("span", "detail-id", inc.id));
    var sev = el("span", "sev sev-" + inc.severity, inc.severity);
    tline.appendChild(sev);
    body.appendChild(tline);
    body.appendChild(el("h3", "detail-title", inc.title));

    var tags = el("div", "detail-tags");
    var stTag = el("span", "status status-" + inc.status);
    stTag.appendChild(document.createTextNode(inc.status.charAt(0).toUpperCase() + inc.status.slice(1)));
    tags.appendChild(stTag);
    tags.appendChild(el("span", "env", inc.service));
    body.appendChild(tags);

    // Key fields — grid of definition pairs
    var dl = el("dl", "detail-fields");
    [["Service", inc.service, true],
     ["Age", inc.age, true],
     ["Owner", inc.owner, false],
     ["Severity", inc.severity, false],
     ["Status", inc.status, false],
     ["Signal", "auto-detected", false]].forEach(function (f) {
      var wrap = el("div", "field");
      wrap.appendChild(el("dt", null, f[0]));
      wrap.appendChild(el("dd", f[2] ? "mono" : "", f[1]));
      dl.appendChild(wrap);
    });
    body.appendChild(dl);

    // Timeline
    body.appendChild(el("p", "section-label", "Activity"));
    var tl = el("ul", "timeline");
    (TIMELINE[inc.severity] || []).forEach(function (ev) {
      var li = el("li");
      li.appendChild(el("time", null, ev[1]));
      li.appendChild(document.createTextNode(ev[0]));
      tl.appendChild(li);
    });
    if (inc.status === "acknowledged") {
      var li2 = el("li");
      li2.appendChild(el("time", null, "just now"));
      li2.appendChild(document.createTextNode("Acknowledged by on-call operator"));
      tl.appendChild(li2);
    }
    body.appendChild(tl);

    // Acknowledge action — the one state-changing interaction
    var actions = el("div", "detail-actions");
    var ack = el("button", "btn btn-accent");
    ack.type = "button";
    ack.id = "ack-btn";
    if (inc.status === "acknowledged") {
      ack.disabled = true;
      ack.appendChild(icon("i-check"));
      ack.appendChild(document.createTextNode("Acknowledged"));
    } else {
      ack.appendChild(icon("i-check"));
      ack.appendChild(document.createTextNode("Acknowledge"));
      ack.addEventListener("click", function () { acknowledge(inc.id); });
    }
    actions.appendChild(ack);
    body.appendChild(actions);

    var note = el("p", "ack-note");
    note.appendChild(icon("i-keyboard"));
    note.appendChild(document.createTextNode(
      inc.status === "acknowledged"
        ? "This incident is acknowledged and visible to the team."
        : "Shortcut: press A to acknowledge the selected incident."
    ));
    body.appendChild(note);

    host.appendChild(body);
  }

  function acknowledge(id) {
    var inc = selectedIncident();
    if (!inc || inc.id !== id || inc.status === "acknowledged") return;
    inc.status = "acknowledged";
    if (inc.owner === "Unassigned") inc.owner = "On-call operator";
    // Re-render both surfaces so table, status filter and detail stay in sync.
    renderTable();
    renderDetail();
    announce("Incident " + id + " acknowledged. Status updated.");
    // A subtle text confirmation rather than a disruptive toast.
    var btn = $("#ack-btn");
    if (btn) {
      btn.disabled = true;
    }
  }

  /* ----------------------------------------------------------------- clock */
  function startClock() {
    function tick() {
      var t = timeStr(new Date());
      $("#clock").textContent = t;
      $("#sync-time").textContent = t;
    }
    tick();
    setInterval(tick, 1000);
    $("#updated-at").textContent = timeStr(S.lastRefresh);
  }

  function setHealth() {
    var crit = S.incidents.filter(function (x) {
      return x.severity === "critical" && x.status !== "acknowledged";
    }).length;
    var high = S.incidents.filter(function (x) {
      return x.severity === "high" && x.status !== "acknowledged";
    }).length;
    var state = crit ? "critical" : (high ? "degraded" : "ok");
    var labels = {
      critical: crit + " critical · degraded",
      degraded: high + " high · watch",
      ok: "All systems nominal"
    };
    var box = $(".health");
    box.classList.remove("is-ok", "is-degraded", "is-critical");
    box.classList.add("is-" + state);
    $("#health-label").textContent = labels[state];
  }

  /* -------------------------------------------------------------- bindings */
  function clearFilters() {
    S.q = ""; S.severity = "all"; S.status = "all";
    renderFilters();
    renderTable();
    announce("Filters cleared. Showing all incidents.");
  }

  function bindGlobal() {
    // Filter inputs
    $("#q").addEventListener("input", function (e) {
      S.q = e.target.value;
      renderTable();
    });
    $("#f-severity").addEventListener("change", function (e) {
      S.severity = e.target.value;
      renderTable();
      announce(visibleIncidents().length + " incidents match the current filters");
    });
    $("#f-status").addEventListener("change", function (e) {
      S.status = e.target.value;
      renderTable();
      announce(visibleIncidents().length + " incidents match the current filters");
    });
    $("#reset").addEventListener("click", clearFilters);
    $("#empty-clear").addEventListener("click", clearFilters);

    // Table: click / keyboard selection
    $("#inc-body").addEventListener("click", function (e) {
      var r = e.target.closest(".inc-row");
      if (r) selectRow(r.dataset.id, false);
    });
    $("#inc-body").addEventListener("keydown", function (e) {
      var r = e.target.closest(".inc-row");
      if (!r) return;
      var rows = $$(".inc-row");
      var idx = rows.indexOf(r);
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault(); selectRow(r.dataset.id, false);
      } else if (e.key === "ArrowDown" || e.key === "ArrowUp") {
        e.preventDefault();
        var next = rows[idx + (e.key === "ArrowDown" ? 1 : -1)];
        if (next) { next.focus(); selectRow(next.dataset.id, false); }
      }
    });

    // Chart arrow-key stepping
    $("#chart-plot").addEventListener("keydown", function (e) {
      if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
      var bars = $$(".bar");
      if (!bars.length) return;
      var cur = S.focusHour == null ? 0 : S.focusHour;
      var next = Math.min(bars.length - 1, Math.max(0, cur + (e.key === "ArrowRight" ? 1 : -1)));
      e.preventDefault();
      bars[next].focus();
    });

    // Refresh button — re-reads metrics/clock and reconfirms the live state
    $("#refresh").addEventListener("click", function () {
      S.lastRefresh = new Date();
      $("#updated-at").textContent = timeStr(S.lastRefresh);
      setHealth();
      announce("Telemetry refreshed at " + timeStr(S.lastRefresh));
    });

    // Nav rail: active state + view name in the breadcrumb
    $$(".rail-nav .nav-item").forEach(function (item) {
      item.addEventListener("click", function () {
        if (item.id === "help-open") return; // handled below
        $$(".rail-nav .nav-item").forEach(function (n) { n.classList.remove("is-active"); });
        item.classList.add("is-active");
        $("#view-name").textContent = item.dataset.nav;
      });
    });
    // ESC inside nav clears the active highlight back to Overview
    $(".rail-nav").addEventListener("keydown", function (e) {
      if (e.key !== "Escape") return;
      $$(".rail-nav .nav-item").forEach(function (n) { n.classList.remove("is-active"); });
      var ov = $('[data-nav="Overview"]');
      if (ov) ov.classList.add("is-active");
      $("#view-name").textContent = "Overview";
    });

    // Keyboard help dialog
    var dlg = $("#help");
    function openHelp() {
      if (typeof dlg.showModal === "function") dlg.showModal();
      else dlg.setAttribute("open", "");
      $("#help-close").focus();
    }
    function closeHelp() {
      if (typeof dlg.close === "function" && dlg.open) dlg.close();
      else dlg.removeAttribute("open");
    }
    $("#help-open").addEventListener("click", openHelp);
    $("#foot-help").addEventListener("click", openHelp);
    $("#help-close").addEventListener("click", closeHelp);
    dlg.addEventListener("click", function (e) { if (e.target === dlg) closeHelp(); });

    // Global shortcuts (ignored while typing, except Esc, and while dialog open)
    document.addEventListener("keydown", function (e) {
      var typing = /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName) || e.target.isContentEditable;
      var dialogOpen = dlg.open || dlg.hasAttribute("open");

      if (e.key === "Escape") {
        if (dialogOpen) { closeHelp(); return; }
        if (typing && e.target.id === "q") { e.target.value = ""; S.q = ""; renderTable(); e.target.blur(); }
        return;
      }
      if (dialogOpen || typing || e.ctrlKey || e.metaKey || e.altKey) return;

      if (e.key === "/") {
        e.preventDefault(); $("#q").focus(); $("#q").select();
        return;
      }
      if (e.key === "a" || e.key === "A") {
        var inc = selectedIncident();
        if (inc && inc.status !== "acknowledged") { e.preventDefault(); acknowledge(inc.id); }
      }
    });
  }

  /* ------------------------------------------------------------------- run */
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

