// Injected into a copy of index.html via <script src="_test.js">.
// Runs after app.js; simulates the full interaction surface and reports results.
(function () {
  var results = [];
  function ok(name, cond, extra) { results.push((cond ? "PASS" : "FAIL") + " | " + name + (extra ? " | " + extra : "")); }
  function q(s, r) { return (r || document).querySelector(s); }
  function qa(s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); }
  function fire(node, type) { node.dispatchEvent(new Event(type, { bubbles: true })); }
  function key(node, k) {
    node.dispatchEvent(new KeyboardEvent("keydown", { key: k, bubbles: true, cancelable: true }));
  }
  function click(node) { node.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true })); }

  try {
    // --- baseline ---
    ok("4 metrics rendered", qa(".metric").length === 4);
    ok("24 chart bars rendered", qa(".bar").length === 24);
    ok("4 incident rows rendered", qa(".inc-row").length === 4);
    ok("default selection is INC-2841", q(".inc-row.is-selected") && q(".inc-row.is-selected").dataset.id === "INC-2841");
    ok("detail shows selected title", /Card authorization timeouts/.test(q(".detail-title").textContent));
    ok("health shows critical degraded", /critical/.test(q("#health-label").textContent));
    ok("y-axis has 5 gridline labels", qa("#chart-yaxis span").length === 5);
    ok("over-target bars flagged", qa(".bar.over").length === 2, "count=" + qa(".bar.over").length);

    // --- metric trend semantics ---
    var chips = qa(".trend-chip");
    ok("Events/min +8.2% is favourable (good)", chips[0].classList.contains("good"));
    ok("P95 −12ms is favourable (good)", chips[1].classList.contains("good"));
    ok("Error rate +0.08pp is bad", chips[2].classList.contains("bad"));
    ok("Queue depth −19% is good", chips[3].classList.contains("good"));

    // --- text filter ---
    var qi = q("#q");
    qi.value = "webhooks"; fire(qi, "input");
    ok("text filter yields 1 row", qa(".inc-row").length === 1, "rows=" + qa(".inc-row").length);
    ok("text filter shows webhooks", /webhooks/.test(q(".inc-row .inc-service").textContent));
    ok("count reflects filtered result", /1 of 4/.test(q("#result-count").textContent));
    // filter also reassigns selection to the visible row
    ok("selection reassigned to visible row", q(".inc-row.is-selected") && q(".inc-row.is-selected").dataset.id === "INC-2832");

    qi.value = "zzzz-no-match"; fire(qi, "input");
    ok("unmatched text shows empty state", q("#empty").hidden === false);
    ok("table hidden in empty state", q(".inc-table").hidden === true);
    ok("empty state explains active filter", /zzzz-no-match/.test(q("#empty-detail").textContent));
    // clear via empty-clear button
    click(q("#empty-clear"));
    ok("empty-clear restores all rows", qa(".inc-row").length === 4, "rows=" + qa(".inc-row").length);

    // --- severity select filter ---
    var sev = q("#f-severity");
    sev.value = "critical"; fire(sev, "change");
    ok("severity filter -> 1 critical row", qa(".inc-row").length === 1);
    ok("critical row is INC-2841", /INC-2841/.test(q(".inc-row .inc-id").textContent));

    // --- combined filter with no matches (empty filter state) ---
    qi.value = "payments"; fire(qi, "input"); // payments-api + severity=critical -> 1
    ok("combined text+severity -> 1 row", qa(".inc-row").length === 1, "rows=" + qa(".inc-row").length);
    sev.value = "low"; fire(sev, "change");
    ok("conflicting filters -> empty state", q("#empty").hidden === false);
    ok("empty detail lists both active filters", /payments/.test(q("#empty-detail").textContent) && /low/.test(q("#empty-detail").textContent));

    // --- reset ---
    click(q("#reset"));
    ok("reset clears all 3 filters", q("#q").value === "" && q("#f-severity").value === "all" && q("#f-status").value === "all");
    ok("reset restores 4 rows", qa(".inc-row").length === 4);

    // --- status filter ---
    var st = q("#f-status");
    st.value = "investigating"; fire(st, "change");
    ok("status filter -> 1 investigating row", qa(".inc-row").length === 1);
    click(q("#reset"));

    // --- row selection via click ---
    var rows = qa(".inc-row");
    var highRow = rows.filter(function (r) { return r.dataset.id === "INC-2839"; })[0];
    click(highRow);
    ok("click selects INC-2839", q(".inc-row.is-selected").dataset.id === "INC-2839");
    ok("detail updates to EU retry queue growth", /EU retry queue growth/.test(q(".detail-title").textContent));
    ok("aria-selected true on clicked row", highRow.getAttribute("aria-selected") === "true");

    // --- acknowledge action (button) ---
    var ackBtn = q("#ack-btn");
    ok("ack button enabled for open incident", ackBtn && !ackBtn.disabled);
    click(ackBtn);
    ok("ack button now disabled + labelled Acknowledged", q("#ack-btn").disabled === true && /Acknowledged/.test(q("#ack-btn").textContent));
    ok("detail status shows acknowledged", /status-acknowledged/.test(q(".detail-tags").innerHTML));
    var ackRow = q('.inc-row[data-id="INC-2839"]');
    ok("table row status now acknowledged", /Acknowledged/.test(ackRow.querySelector(".status").textContent));
    ok("Unassigned owner replaced on ack", !/Unassigned/.test(q(".detail-fields").textContent));
    ok("timeline includes acknowledgement event", /Acknowledged by on-call/.test(q(".timeline").textContent));

    // --- acknowledge via keyboard shortcut 'A' on a fresh incident ---
    // select INC-2837 via click, then press A on document
    click(q('.inc-row[data-id="INC-2837"]'));
    ok("selected INC-2837 via click", q(".inc-row.is-selected").dataset.id === "INC-2837");
    key(document, "a");
    ok("keyboard A acknowledges INC-2837", /Acknowledged/.test(q('.inc-row[data-id="INC-2837"] .status').textContent));

    // --- status filter now reflects the acknowledged rows ---
    st.value = "acknowledged"; fire(st, "change");
    ok("acknowledged status filter -> 2 rows", qa(".inc-row").length === 2, "rows=" + qa(".inc-row").length);
    click(q("#reset"));

    // --- keyboard: '/' focuses filter ---
    key(document, "/");
    ok("'/' focuses filter input", document.activeElement.id === "q");

    // --- Escape clears focused filter field ---
    key(q("#q"), "Escape");
    ok("Escape blurs/clears filter field", document.activeElement.id !== "q");

    // --- chart bar focus + arrow stepping ---
    var bars = qa(".bar");
    bars[0].focus();
    ok("focusing a bar shows readout", /hour 1 of 24/.test(q("#chart-readout").textContent), q("#chart-readout").textContent.slice(0, 40));
    ok("focused bar has is-focus class", bars[0].classList.contains("is-focus"));
    key(q("#chart-plot"), "ArrowRight");
    ok("ArrowRight moves focus to bar 2", document.activeElement === bars[1] || bars[1].classList.contains("is-focus"));

    // --- row arrow-key navigation ---
    var r0 = qa(".inc-row")[0];
    r0.focus();
    key(q("#inc-body"), "ArrowDown");
    ok("ArrowDown moves to next row", document.activeElement === qa(".inc-row")[1]);

    // --- Enter selects focused row ---
    var r2 = qa(".inc-row")[2];
    r2.focus();
    key(q("#inc-body"), "Enter");
    ok("Enter selects focused row", q(".inc-row.is-selected") === r2);

    // --- help dialog open/close ---
    click(q("#help-open"));
    ok("help dialog opens", q("#help").open === true);
    key(document, "Escape");
    ok("Escape closes help dialog", q("#help").open === false);

    // --- nav rail active state + breadcrumb ---
    click(q('[data-nav="Throughput"]'));
    ok("nav sets active on Throughput", q('[data-nav="Throughput"]').classList.contains("is-active"));
    ok("breadcrumb view-name updates", q("#view-name").textContent === "Throughput");

