// Mobile layout verification. Loaded inside a 390px iframe by _mobile.html.
// Measures horizontal overflow of the document and of every major region.
(function () {
  function report() {
    var out = [];
    var d = document.documentElement;
    out.push("viewport=" + window.innerWidth + " scrollWidth=" + d.scrollWidth +
             " bodyScroll=" + document.body.scrollWidth);
    out.push("HORIZONTAL_OVERFLOW=" + (d.scrollWidth > window.innerWidth + 1 ? "YES" : "NO"));

    // Identify any element whose right edge exceeds the viewport width.
    var widths = [];
    var all = document.querySelectorAll("body *");
    for (var i = 0; i < all.length; i++) {
      var n = all[i];
      var r = n.getBoundingClientRect();
      if (r.width === 0 && r.height === 0) continue; // hidden
      if (r.right > window.innerWidth + 1 || r.left < -1) {
        widths.push((n.id ? "#" + n.id : (n.className && typeof n.className === "string" ? "." + n.className.split(" ")[0] : n.tagName.toLowerCase())) +
                    " L=" + Math.round(r.left) + " R=" + Math.round(r.right) + " W=" + Math.round(r.width));
      }
    }
    out.push("OVERFLOWING_ELEMENTS=" + (widths.length ? widths.length : 0));
    widths.slice(0, 12).forEach(function (w) { out.push("  " + w); });

    // Key structural checks at mobile size
    out.push("rail is horizontal strip=" + (getComputedStyle(document.querySelector(".rail")).flexDirection === "row"));
    out.push("metrics columns=" + getComputedStyle(document.querySelector(".metrics")).gridTemplateColumns);
    out.push("lower columns=" + getComputedStyle(document.querySelector(".lower")).gridTemplateColumns);
    out.push("title column hidden=" + (getComputedStyle(document.querySelector(".inc-table th:nth-child(3)")).display === "none"));
    out.push("owner column hidden=" + (getComputedStyle(document.querySelector(".inc-table th:nth-child(5)")).display === "none"));
    out.push("rows=" + document.querySelectorAll(".inc-row").length);
    out.push("bars=" + document.querySelectorAll(".bar").length);
    out.push("detail rendered=" + !!document.querySelector(".detail-title"));

    var pre = document.createElement("pre");
    pre.id = "mobile-report";
    pre.style.cssText = "font:11px monospace;color:#e3e8ec;background:#0d1013;padding:12px;white-space:pre-wrap";
    pre.textContent = out.join("\n");
    document.body.innerHTML = "";
    document.body.appendChild(pre);
  }
  function wait() {
    if (document.querySelector(".metric") && document.querySelector(".inc-row")) { setTimeout(report, 100); return; }
    setTimeout(wait, 50);
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () { setTimeout(wait, 30); });
  } else { setTimeout(wait, 30); }
})();

