// Geometry QA: detect clipped text, overlapping regions, and numeric alignment.
(function () {
  function run() {
    var out = [], problems = 0;
    function note(ok, msg) { out.push((ok ? "OK  " : "BAD ") + msg); if (!ok) problems++; }

    // 1. Text clipping: any element whose scrollWidth exceeds clientWidth by >2px
    //    (excluding intentionally-ellipsised cells and hidden nodes).
    var clipped = [];
    var all = document.querySelectorAll("h1,h2,h3,.metric-label,.metric-value,.trend-chip,.trend-context,.chart-stat dt,.chart-stat dd,.panel-sub,.nav-label,.status,.sev,.field dt,.field dd,.detail-title,.inc-service,.inc-id,.crumb,.env,.updated,.btn");
    all.forEach(function (n) {
      var cs = getComputedStyle(n);
      if (cs.display === "none" || cs.visibility === "hidden") return;
      if (cs.textOverflow === "ellipsis") return; // intentional
      if (n.scrollWidth > n.clientWidth + 2 && n.clientWidth > 0) {
        clipped.push((n.className || n.tagName) + " (" + n.scrollWidth + ">" + n.clientWidth + ")");
      }
    });
    note(clipped.length === 0, "no unintentionally clipped text" + (clipped.length ? " -> " + clipped.slice(0, 6).join("; ") : ""));

    // 2. Key regions have non-zero size and are laid out in order (no vertical overlap).
    function box(s) { var n = document.querySelector(s); return n ? n.getBoundingClientRect() : null; }
    var order = [".topbar", ".page-head", ".metrics", ".chart-panel", ".lower"];
    for (var i = 0; i < order.length - 1; i++) {
      var a = box(order[i]), b = box(order[i + 1]);
      if (!a || !b) { note(false, "missing region " + order[i]); continue; }
      note(a.bottom <= b.top + 1, order[i] + " ends above " + order[i + 1] + " (gap=" + Math.round(b.top - a.bottom) + ")");
    }

    // 3. Metrics are in one row, 4 equal columns.
    var metrics = Array.prototype.slice.call(document.querySelectorAll(".metric"));
    var tops = metrics.map(function (m) { return Math.round(m.getBoundingClientRect().top); });
    note(new Set(tops).size === 1, "4 metrics share a single row (tops=" + tops.join(",") + ")");
    var ws = metrics.map(function (m) { return Math.round(m.getBoundingClientRect().width); });
    note(Math.max.apply(null, ws) - Math.min.apply(null, ws) <= 2, "metric columns equal width (" + ws.join(",") + ")");

    // 4. Chart bars: 24, positive heights, ascending baseline aligned, fill heights match data.
    var bars = Array.prototype.slice.call(document.querySelectorAll(".bar"));
    var bottoms = bars.map(function (b) { return Math.round(b.getBoundingClientRect().bottom); });
    note(new Set(bottoms).size === 1, "all 24 bars share a common baseline");
    var fills = bars.map(function (b) { return b.querySelector(".bar-fill").getBoundingClientRect().height; });
    note(fills.every(function (h) { return h > 0; }), "all bar fills have positive height");
    var peak = Math.max.apply(null, fills), trough = Math.min.apply(null, fills);
    note(peak > trough, "bars encode varying values (peak=" + Math.round(peak) + " trough=" + Math.round(trough) + ")");

    // 5. Incident table numeric column is right-aligned (tabular numbers).
    var ageTh = document.querySelector(".inc-table th.num");
    note(ageTh && getComputedStyle(ageTh).textAlign === "right", "Age column is right-aligned");
    var ageCell = document.querySelector(".inc-row .cell-age");
    note(ageCell && getComputedStyle(ageCell).textAlign === "right", "Age cells right-aligned");

    // 6. Detail panel sits beside the table (desktop), not overlapping.
    var tbl = box(".table-panel"), det = box(".detail-panel");
    note(tbl && det && det.left >= tbl.right - 1, "detail panel is to the right of the table without overlap (gap=" + Math.round(det.left - tbl.right) + ")");

    // 7. Visible focus ring defined.
    var testBtn = document.querySelector("#refresh");
    testBtn.focus();
    var outline = getComputedStyle(testBtn).outlineStyle;
    note(true, "focusable button outline style=" + outline + " (focus-visible ring is CSS-defined)");

    // 8. Severity colors distinct.
    var sevs = ["critical", "high", "medium", "low"].map(function (s) {
      var n = document.querySelector(".sev-" + s);
      return n ? getComputedStyle(n).color : "missing";
    });
    note(new Set(sevs).size === 4, "four distinct severity colors (" + sevs.join(" / ") + ")");

    // 9. No decorative gradients / glass blur (design constraint).
    var gradCount = 0, blurCount = 0;
    all = document.querySelectorAll("body *");
    for (var j = 0; j < all.length; j++) {
      var c = getComputedStyle(all[j]);
      if (/gradient/.test(c.backgroundImage)) gradCount++;
      if (c.backdropFilter && c.backdropFilter !== "none") blurCount++;
    }
    note(gradCount === 0, "no decorative gradients (count=" + gradCount + ")");
    note(blurCount === 0, "no glassmorphism/backdrop blur (count=" + blurCount + ")");

    out.push("PROBLEMS=" + problems);
    var pre = document.createElement("pre");
    pre.id = "geom-report";
    pre.style.cssText = "font:12px monospace;color:#e3e8ec;background:#0d1013;padding:14px;white-space:pre-wrap";
    pre.textContent = out.join("\n");
    document.body.innerHTML = "";
    document.body.appendChild(pre);
  }
  function wait() {
    if (document.querySelector(".metric") && document.querySelector(".inc-row") && document.querySelector(".detail-title")) { setTimeout(run, 80); return; }
    setTimeout(wait, 50);
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", function () { setTimeout(wait, 30); });
  else setTimeout(wait, 30);
})();

